window.I18N={"nav.home":{"ta":"முகப்பு","hi":"होम"},"nav.services":{"ta":"சேவைகள்","hi":"सेवाएं"},"nav.packages":{"ta":"பேக்கேஜ்கள்","hi":"पैकेज"},"nav.gallery":{"ta":"கேலரி","hi":"गैलरी"},"nav.about":{"ta":"எங்களை பற்றி","hi":"हमारे बारे में"},"nav.faq":{"ta":"கேள்விகள்","hi":"सवाल"},"nav.contact":{"ta":"தொடர்பு","hi":"संपर्क"},"nav.book":{"ta":"புக் செய்ய","hi":"अभी बुक करें"},"loc.short":{"ta":"களந்தபனை, திருநெல்வேலி","hi":"कलंथपनई, तिरुनेलवेली"},"loc.full":{"ta":"களந்தபனை, திருநெல்வேலி, தமிழ்நாடு","hi":"कलंथपनई, तिरुनेलवेली, तमिलनाडु"},"hours.short":{"ta":"தினமும் காலை 9 – இரவு 8","hi":"प्रतिदिन सुबह 9 – रात 8"},"brand":{"ta":"கிங் ஈவென்ட்ஸ்","hi":"किंग इवेंट्स"},"hero.h1":{"ta":"உங்கள் கொண்டாட்டம்.<br><em>எங்கள் ராஜ படைப்பு.</em>","hi":"आपका उत्सव।<br><em>हमारी शाही रचना।</em>"},"hero.lead":{"ta":"திருமண அலங்காரம், மண்டபம், ராஜ விருந்து மற்றும் கேளிக்கை ஸ்டால்கள் — உங்கள் சிறப்பு நாளுக்கு தேவையான அனைத்தும், திருநெல்வேலி நிகழ்ச்சி குழுவிடமிருந்து.","hi":"शादी की सजावट, मंडप, शाही कैटरिंग और फन स्टॉल — आपके खास दिन के लिए सब कुछ, तिरुनेलवेली की इवेंट टीम से।"},"btn.explore":{"ta":"சேவைகளை பார்க்க","hi":"सेवाएं देखें"},"btn.quote":{"ta":"இலவச விலை விவரம்","hi":"मुफ्त कोटेशन पाएं"},"btn.call":{"ta":"இப்போது அழைக்க","hi":"अभी कॉल करें"},"btn.wa":{"ta":"வாட்ஸ்அப் செய்ய","hi":"व्हाट्सऐप करें"},"btn.book":{"ta":"இந்த பேக்கேஜை புக் செய்ய","hi":"यह पैकेज बुक करें"},"btn.gallery":{"ta":"முழு கேலரி பார்க்க","hi":"पूरी गैलरी देखें"},"btn.more":{"ta":"மேலும் அறிய →","hi":"और जानें →"},"btn.enquire":{"ta":"விசாரிக்க","hi":"पूछताछ करें"},"stat.years":{"ta":"ஆண்டுகள் ராஜ பாரம்பரியம்","hi":"वर्षों की शाही परंपरा"},"stat.events":{"ta":"கொண்டாடிய நிகழ்ச்சிகள்","hi":"सम्पन्न आयोजन"},"stat.services":{"ta":"முழுமையான சேவைகள்","hi":"संपूर्ण सेवाएं"},"stat.districts":{"ta":"சேவை மாவட்டங்கள்","hi":"सेवा वाले जिले"},"sec.services.eyebrow":{"ta":"நாங்கள் செய்வது","hi":"हम क्या करते हैं"},"sec.services.h2":{"ta":"எங்கள் சேவைகள்","hi":"हमारी सेवाएं"},"sec.services.p":{"ta":"உங்கள் கொண்டாட்டத்திற்கு தேவையான அனைத்தும், ஒரே இடத்தில்.","hi":"आपके उत्सव की हर ज़रूरत, एक ही छत के नीचे।"},"s1.t":{"ta":"திருமண அலங்காரம்","hi":"विवाह सजावट"},"s1.d":{"ta":"புதிய சாமந்தி, மல்லிகை, பித்தளை விளக்குகள் மற்றும் பிரம்மாண்ட பின்னணியுடன் பாரம்பரிய மற்றும் நவீன திருமண மேடை அலங்காரம்.","hi":"ताज़ा गेंदे, चमेली, पीतल के दीपक और भव्य बैकड्रॉप के साथ पारंपरिक व आधुनिक विवाह मंच सजावट।"},"s1.i":{"ta":"உள்ளடக்கம்: மேடை & பின்னணி, நுழைவு தோரணம், மலர் அலங்காரம், பித்தளை விளக்குகள், விளக்கொளி.","hi":"शामिल: मंच व बैकड्रॉप, प्रवेश तोरण, फूलों की सजावट, पीतल के दीपक, लाइटिंग।"},"s2.t":{"ta":"வரவேற்பு அலங்காரம்","hi":"रिसेप्शन सजावट"},"s2.d":{"ta":"மலர் வளைவுகள், சூடான சரவிளக்குகள் மற்றும் ராஜ இருக்கைகளுடன் நேர்த்தியான வரவேற்பு மேடை மற்றும் அரங்க அலங்காரம்.","hi":"फूलों के आर्च, गर्म रोशनी वाले झूमर और शाही बैठक के साथ सुरुचिपूर्ण रिसेप्शन स्टेज व वेन्यू सजावट।"},"s2.i":{"ta":"உள்ளடக்கம்: வரவேற்பு மேடை, மலர் வளைவு, சோபா இருக்கை, புகைப்பட பின்னணி, சரவிளக்கு ஒளி.","hi":"शामिल: रिसेप्शन स्टेज, फूलों का आर्च, सोफ़ा, फ़ोटो बैकड्रॉप, झूमर लाइटिंग।"},"s3.t":{"ta":"நிச்சயதார்த்த அலங்காரம்","hi":"सगाई सजावट"},"s3.d":{"ta":"அலங்கரிக்கப்பட்ட ஊஞ்சல், மென்மையான மலர்கள் மற்றும் மின்னும் விளக்குகளுடன் அழகான மலர் மற்றும் பாரம்பரிய அமைப்புகள்.","hi":"सजे हुए झूले, पेस्टल फूलों और जगमगाती परी रोशनी के साथ सुंदर फूलों व पारंपरिक सेटअप।"},"s3.i":{"ta":"உள்ளடக்கம்: ஊஞ்சல் அல்லது வளைய அமைப்பு, மலர் ஸ்டாண்டுகள், மின்விளக்குகள், பெயர்ப் பலகை, மெழுகுவர்த்திகள்.","hi":"शामिल: झूला या रिंग-आर्च सेटअप, फ्लॉवर स्टैंड, फेयरी लाइट, नेम बोर्ड, मोमबत्तियां।"},"s4.t":{"ta":"கேட்டரிங்","hi":"कैटरिंग"},"s4.d":{"ta":"சுவையான பாரம்பரிய உணவு மற்றும் தொழில்முறை சேவை — வாழை இலை விருந்து மற்றும் பிரம்மாண்ட பஃபே.","hi":"स्वादिष्ट पारंपरिक भोजन और पेशेवर सेवा — केले के पत्ते की दावत और भव्य बुफे।"},"s4.i":{"ta":"உள்ளடக்கம்: பாரம்பரிய மெனு, வாழை இலை பரிமாறல், பயிற்சி பெற்ற பணியாளர்கள், பஃபே கவுண்டர்கள்.","hi":"शामिल: पारंपरिक मेन्यू, केले के पत्ते में परोसना, प्रशिक्षित स्टाफ, बुफे काउंटर।"},"s5.t":{"ta":"பாப்கார்ன் ஸ்டால்","hi":"पॉपकॉर्न स्टॉल"},"s5.d":{"ta":"திருமணம், பிறந்தநாள், சங்கீத் இரவுகளில் மகிழ்ச்சியும் மணமும் தரும் புதிய பாப்கார்ன் கவுண்டர்கள்.","hi":"शादी, जन्मदिन और संगीत की रातों में मज़ा और खुशबू लाने वाले ताज़ा पॉपकॉर्न काउंटर।"},"s5.i":{"ta":"உள்ளடக்கம்: நேரடி பாப்கார்ன் இயந்திரம், சுவை தேர்வுகள், இயக்குநர், அலங்கரிக்கப்பட்ட கவுண்டர்.","hi":"शामिल: लाइव पॉपकॉर्न मशीन, फ्लेवर विकल्प, ऑपरेटर, सजा हुआ काउंटर।"},"s6.t":{"ta":"பஞ்சு மிட்டாய்","hi":"कॉटन कैंडी"},"s6.d":{"ta":"வண்ணமயமான பஞ்சு மிட்டாய் — குழந்தைகளுக்கும் விருந்தினர்களுக்கும் மகிழ்ச்சி.","hi":"रंग-बिरंगी कॉटन कैंडी — बच्चों और मेहमानों के लिए जादुई मज़ा।"},"s6.i":{"ta":"உள்ளடக்கம்: நேரடி பஞ்சு மிட்டாய் இயந்திரம், வண்ண தேர்வுகள், இயக்குநர், அலங்கரிக்கப்பட்ட கவுண்டர்.","hi":"शामिल: लाइव कॉटन कैंडी मशीन, रंग विकल्प, ऑपरेटर, सजा हुआ काउंटर।"},"s7.t":{"ta":"முழு நிகழ்ச்சி அலங்காரம்","hi":"संपूर्ण इवेंट सजावट"},"s7.d":{"ta":"நுழைவு தோரணங்கள், பாதை விளக்குகள், உணவு அரங்க அலங்காரம் மற்றும் தீம் ஒருங்கிணைப்பு — முழுமையான அரங்க மாற்றம்.","hi":"प्रवेश तोरण, पथ रोशनी, डाइनिंग सजावट और थीम समन्वय — पूरे वेन्यू का संपूर्ण रूपांतरण।"},"s7.i":{"ta":"உள்ளடக்கம்: நுழைவு, பாதை, உணவு அரங்கம், மேடை மற்றும் விளக்கொளி — அனைத்தும் ஒரே குழுவிடம்.","hi":"शामिल: प्रवेश, पथ, डाइनिंग एरिया, मंच और लाइटिंग — सब कुछ एक ही टीम से।"},"why.eyebrow":{"ta":"ஏன் கிங் ஈவென்ட்ஸ்","hi":"किंग इवेंट्स क्यों"},"why.h2":{"ta":"ராஜ சேவை, குடும்ப அன்பு","hi":"शाही सेवा, पारिवारिक अपनापन"},"w1.t":{"ta":"உண்மையான பாரம்பரியம்","hi":"प्रामाणिक परंपरा"},"w1.d":{"ta":"உங்கள் குடும்பம் எதிர்பார்க்கும் முறையில் மண்டபமும் சடங்கு அமைப்பும்.","hi":"मंडप और रीति-रिवाज वैसे ही सजाए जाते हैं जैसा आपका परिवार चाहता है।"},"w2.t":{"ta":"ஒரே குழு, எல்லாமும்","hi":"एक टीम, सब कुछ"},"w2.d":{"ta":"அலங்காரம், கேட்டரிங், கேளிக்கை ஸ்டால்கள் — ஒரே புக்கிங், ஒரே தொடர்பு.","hi":"सजावट, कैटरिंग और फन स्टॉल — एक बुकिंग, एक संपर्क।"},"w3.t":{"ta":"புதிய மலர்கள்","hi":"ताज़े फूल"},"w3.d":{"ta":"உங்கள் நிகழ்ச்சி நாளுக்கு புதிதாக வாங்கிய சாமந்தி, மல்லிகை, ரோஜா.","hi":"आपके इवेंट के दिन के लिए ताज़ा गेंदा, चमेली और गुलाब।"},"w4.t":{"ta":"பட்ஜெட்டுக்கு ஏற்றது","hi":"बजट के अनुकूल"},"w4.d":{"ta":"மறைமுக கட்டணம் இல்லாத தெளிவான விலை — ஒவ்வொரு பட்ஜெட்டுக்கும் பேக்கேஜ்.","hi":"बिना छिपे शुल्क के साफ कोटेशन — हर बजट के लिए पैकेज।"},"proc.eyebrow":{"ta":"எப்படி செயல்படுகிறது","hi":"यह कैसे काम करता है"},"proc.h2":{"ta":"விசாரணையிலிருந்து கொண்டாட்டம் வரை","hi":"पूछताछ से उत्सव तक"},"p1.t":{"ta":"விசாரிக்கவும்","hi":"पूछताछ"},"p1.d":{"ta":"அழைக்கவும், வாட்ஸ்அப் செய்யவும் அல்லது தேதி மற்றும் தேவைகளுடன் படிவம் நிரப்பவும்.","hi":"कॉल करें, व्हाट्सऐप करें या तारीख और ज़रूरतों के साथ फॉर्म भरें।"},"p2.t":{"ta":"திட்டமிடுங்கள்","hi":"योजना"},"p2.d":{"ta":"அரங்கத்தைப் பற்றி பேசி, வடிவமைப்பு யோசனைகள் மற்றும் விலை பகிர்வோம்.","hi":"हम वेन्यू पर चर्चा कर डिज़ाइन आइडिया और कोटेशन साझा करते हैं।"},"p3.t":{"ta":"உறுதி செய்யுங்கள்","hi":"पुष्टि"},"p3.d":{"ta":"பேக்கேஜை தேர்வு செய்து முன்பணம் செலுத்தினால் உங்கள் தேதி உறுதி.","hi":"पैकेज चुनें, अग्रिम दें और आपकी तारीख पक्की।"},"p4.t":{"ta":"கொண்டாடுங்கள்","hi":"उत्सव मनाएं"},"p4.d":{"ta":"எங்கள் குழு அனைத்தையும் அமைக்கும் — நீங்கள் கொண்டாட்டத்தை அனுபவியுங்கள்.","hi":"हमारी टीम सब कुछ सजाती है — आप बस उत्सव का आनंद लें।"},"pk.eyebrow":{"ta":"பேக்கேஜ்கள்","hi":"पैकेज"},"pk.h2":{"ta":"உங்கள் பேக்கேஜை தேர்வு செய்யுங்கள்","hi":"अपना पैकेज चुनें"},"pk.p":{"ta":"ஒவ்வொரு பட்ஜெட்டுக்கும் தெளிவான ஆரம்ப விலை.","hi":"हर बजट के लिए साफ शुरुआती कीमतें।"},"pk.from":{"ta":"ஆரம்ப விலை","hi":"शुरुआती कीमत"},"pk.popular":{"ta":"மிகவும் பிரபலம்","hi":"सबसे लोकप्रिय"},"pk.note":{"ta":"* ஆரம்ப விலைகள். இறுதி விலை அரங்கம், தேதி, வடிவமைப்பைப் பொறுத்தது — துல்லியமான மதிப்பீட்டிற்கு தொடர்பு கொள்ளவும்.","hi":"* शुरुआती कीमतें। अंतिम कोटेशन वेन्यू, तारीख और डिज़ाइन पर निर्भर है — सटीक अनुमान के लिए संपर्क करें।"},"pk.addons":{"ta":"கூடுதல் விருப்பங்கள்","hi":"वैकल्पिक ऐड-ऑन"},"pk.a4":{"ta":"கூடுதல் மலர் அலங்காரம்","hi":"अतिरिक्त फूलों की सजावट"},"pk.a5":{"ta":"தனிப்பயன் தீம்","hi":"कस्टम थीम"},"pk1.n":{"ta":"கிளாசிக்","hi":"क्लासिक"},"pk1.f1":{"ta":"புதிய மலர்களுடன் மேடை அலங்காரம்","hi":"ताज़े फूलों के साथ मंच सजावट"},"pk1.f2":{"ta":"நுழைவு தோரணம்","hi":"प्रवेश तोरण"},"pk1.f3":{"ta":"அடிப்படை விளக்கொளி","hi":"बेसिक लाइटिंग"},"pk1.f4":{"ta":"200 விருந்தினர்கள் வரை","hi":"200 मेहमानों तक"},"pk2.n":{"ta":"ராயல்","hi":"रॉयल"},"pk2.f1":{"ta":"மலர் வளைவுடன் பிரம்மாண்ட மேடை","hi":"फूलों के आर्च के साथ भव्य मंच"},"pk2.f2":{"ta":"நுழைவு & பாதை அலங்காரம்","hi":"प्रवेश व पथ सजावट"},"pk2.f3":{"ta":"டிசைனர் விளக்கொளி & புகைப்பட பின்னணி","hi":"डिज़ाइनर लाइटिंग व फ़ोटो बैकड्रॉप"},"pk2.f4":{"ta":"பாப்கார்ன் அல்லது பஞ்சு மிட்டாய் ஸ்டால்","hi":"पॉपकॉर्न या कॉटन कैंडी स्टॉल"},"pk2.f5":{"ta":"500 விருந்தினர்கள் வரை","hi":"500 मेहमानों तक"},"pk3.n":{"ta":"கிராண்ட்","hi":"ग्रैंड"},"pk3.f1":{"ta":"முழுமையான அரங்க மாற்றம்","hi":"संपूर्ण वेन्यू रूपांतरण"},"pk3.f2":{"ta":"மண்டபம், மேடை & உணவு அரங்க அலங்காரம்","hi":"मंडप, मंच व डाइनिंग सजावट"},"pk3.f3":{"ta":"கேட்டரிங் ஒருங்கிணைப்பு","hi":"कैटरिंग समन्वय"},"pk3.f4":{"ta":"பாப்கார்ன் + பஞ்சு மிட்டாய் ஸ்டால்கள்","hi":"पॉपकॉर्न + कॉटन कैंडी स्टॉल"},"pk3.f5":{"ta":"பிரத்யேக நிகழ்ச்சி மேலாளர்","hi":"समर्पित इवेंट मैनेजर"},"pk3.f6":{"ta":"1000+ விருந்தினர்கள்","hi":"1000+ मेहमान"},"gal.eyebrow":{"ta":"எங்கள் பணி","hi":"हमारा काम"},"gal.h2":{"ta":"நாங்கள் உருவாக்கிய கொண்டாட்டங்கள்","hi":"हमारे सजाए उत्सव"},"cat.all":{"ta":"அனைத்தும்","hi":"सभी"},"cat.wedding":{"ta":"திருமணம்","hi":"विवाह"},"cat.reception":{"ta":"வரவேற்பு","hi":"रिसेप्शन"},"cat.engagement":{"ta":"நிச்சயதார்த்தம்","hi":"सगाई"},"cat.catering":{"ta":"கேட்டரிங்","hi":"कैटरिंग"},"cat.entrance":{"ta":"நுழைவு & விளக்கு","hi":"प्रवेश व लाइटिंग"},"cat.stalls":{"ta":"கேளிக்கை ஸ்டால்கள்","hi":"फन स्टॉल"},"h.services":{"ta":"எங்கள் சேவைகள்","hi":"हमारी सेवाएं"},"h.services.p":{"ta":"மண்டப அலங்காரம் முதல் ராஜ விருந்து மற்றும் கேளிக்கை ஸ்டால்கள் வரை.","hi":"मंडप सजावट से लेकर शाही कैटरिंग और फन स्टॉल तक।"},"h.packages":{"ta":"பேக்கேஜ்கள்","hi":"पैकेज"},"h.packages.p":{"ta":"ஒவ்வொரு பட்ஜெட்டுக்கும் தெளிவான ஆரம்ப விலை.","hi":"हर बजट के लिए साफ शुरुआती कीमतें।"},"h.gallery":{"ta":"எங்கள் கேலரி","hi":"हमारी गैलरी"},"h.gallery.p":{"ta":"நாங்கள் அலங்கரித்த கொண்டாட்டங்களின் ஒரு பார்வை.","hi":"हमारी सजाई हुई खुशियों की एक झलक।"},"h.about":{"ta":"எங்களை பற்றி","hi":"हमारे बारे में"},"h.about.p":{"ta":"திருநெல்வேலியின் கொண்டாட்ட குழு.","hi":"तिरुनेलवेली की उत्सव टीम।"},"h.faq":{"ta":"கேள்வி பதில்கள்","hi":"सवाल और जवाब"},"h.faq.p":{"ta":"புக் செய்வதற்கு முன் தெரிந்து கொள்ள வேண்டியவை.","hi":"बुकिंग से पहले जो भी जानना चाहें।"},"h.contact":{"ta":"தொடர்பு கொள்ள","hi":"संपर्क करें"},"h.contact.p":{"ta":"அழைக்கவும், வாட்ஸ்அப் செய்யவும் அல்லது விசாரணை அனுப்பவும் — உங்கள் கொண்டாட்டத்தைப் பற்றி கேட்க ஆவலாக உள்ளோம்.","hi":"कॉल करें, व्हाट्सऐप करें या पूछताछ भेजें — हम आपके उत्सव के बारे में सुनना चाहेंगे।"},"h.404":{"ta":"பக்கம் கிடைக்கவில்லை","hi":"पेज नहीं मिला"},"h.404.p":{"ta":"நீங்கள் தேடும் பக்கம் இல்லை.","hi":"आप जो पेज ढूंढ रहे हैं वह मौजूद नहीं है।"},"ab.story":{"ta":"எங்கள் கதை","hi":"हमारी कहानी"},"ab.p1":{"ta":"ஒவ்வொரு திருநெல்வேலி குடும்பமும் மன அழுத்தமின்றி ராஜ கொண்டாட்டத்தை பெற வேண்டும் என்ற எளிய எண்ணத்தில் கிங் ஈவென்ட்ஸ் தொடங்கியது. களந்தபனையை மையமாகக் கொண்டு, அலங்காரம், கேட்டரிங் மற்றும் கேளிக்கையை ஒரே குழுவாக வழங்குகிறோம்.","hi":"किंग इवेंट्स एक सरल सोच से शुरू हुआ: तिरुनेलवेली के हर परिवार को बिना तनाव के शाही उत्सव मिलना चाहिए। कलंथपनई से हम सजावट, कैटरिंग और मनोरंजन को एक ही टीम के तहत लाते हैं।"},"ab.p2":{"ta":"ஒவ்வொரு திருமணத்தையும் எங்கள் சொந்த குடும்ப விழாவாகவே கருதுகிறோம் — புதிய சாமந்தி, மல்லிகை தோரணங்கள், பித்தளை விளக்குகள், முன்கூட்டியே வந்து கடைசி விருந்தினர் செல்லும் வரை இருக்கும் குழு.","hi":"हम हर शादी को अपने परिवार का समारोह मानते हैं — ताज़ा गेंदे, चमेली के तोरण, पीतल के दीपक और ऐसी टीम जो जल्दी पहुंचती है और आखिरी मेहमान के जाने तक रहती है।"},"ab.areas":{"ta":"நாங்கள் சேவை செய்யும் பகுதிகள்","hi":"हम कहाँ सेवा देते हैं"},"ar.1":{"ta":"களந்தபனை","hi":"कलंथपनई"},"ar.2":{"ta":"திருநெல்வேலி","hi":"तिरुनेलवेली"},"ar.3":{"ta":"தென்காசி","hi":"तेनकासी"},"ar.4":{"ta":"தூத்துக்குடி","hi":"थूथुकुडी"},"ar.5":{"ta":"நாகர்கோவில்","hi":"नागरकोइल"},"ar.6":{"ta":"கன்னியாகுமரி","hi":"कन्याकुमारी"},"q1":{"ta":"எவ்வளவு முன்பே புக் செய்ய வேண்டும்?","hi":"कितनी जल्दी बुक करना चाहिए?"},"a1":{"ta":"முகூர்த்தத்திற்கு 2–3 மாதங்களுக்கு முன் புக் செய்ய பரிந்துரைக்கிறோம், குறிப்பாக திருமண சீசனில். குறுகிய கால தேதிகளும் சாத்தியம் — எங்களை அழைக்கவும்.","hi":"मुहूर्त से 2–3 महीने पहले बुक करने की सलाह है, खासकर शादी के सीज़न में। कम समय में भी संभव है — बस हमें कॉल करें।"},"q2":{"ta":"முன்பணம் எவ்வளவு செலுத்த வேண்டும்?","hi":"अग्रिम कितना देना होगा?"},"a2":{"ta":"முன்பணம் செலுத்தினால் உங்கள் தேதி உறுதியாகும். தொகை மற்றும் மீதித் தொகை அட்டவணை விலைப்பட்டியலில் தெரிவிக்கப்படும்.","hi":"अग्रिम राशि से आपकी तारीख पक्की होती है। राशि और शेष भुगतान का विवरण कोटेशन में बताया जाता है।"},"q3":{"ta":"திருநெல்வேலிக்கு வெளியே சேவை உண்டா?","hi":"क्या आप तिरुनेलवेली के बाहर भी काम करते हैं?"},"a3":{"ta":"ஆம் — அருகிலுள்ள மாவட்டங்களிலும் சேவை செய்கிறோம். தொலைதூர அரங்கங்களுக்கு பயணக் கட்டணம் இருக்கலாம்.","hi":"हां — हम आसपास के जिलों में भी सेवा देते हैं। दूर के वेन्यू के लिए यात्रा शुल्क लग सकता है।"},"q4":{"ta":"கேட்டரிங் இல்லாமல் அலங்காரம் மட்டும் தேர்வு செய்யலாமா?","hi":"क्या मैं कैटरिंग के बिना सिर्फ सजावट ले सकता हूँ?"},"a4":{"ta":"நிச்சயமாக. ஒவ்வொரு சேவையையும் தனியாகவோ பேக்கேஜுடன் சேர்த்தோ புக் செய்யலாம்.","hi":"बिल्कुल। हर सेवा अलग से या पैकेज में बुक की जा सकती है।"},"q5":{"ta":"எங்கள் தீம் அல்லது நிறங்களுக்கு ஏற்ப அலங்காரம் செய்ய முடியுமா?","hi":"क्या सजावट हमारी थीम या रंगों के अनुसार हो सकती है?"},"a5":{"ta":"முடியும். உங்கள் நிறங்கள், மாதிரி புகைப்படங்கள் அல்லது சம்பிரதாயங்களை பகிருங்கள், அதற்கேற்ப வடிவமைப்போம்.","hi":"हां। अपने रंग, रेफ़रेंस फ़ोटो या परंपराएं साझा करें, हम उसी के अनुसार डिज़ाइन करेंगे।"},"q6":{"ta":"சிறிய விழாக்களுக்கும் பாப்கார்ன், பஞ்சு மிட்டாய் ஸ்டால் அமைப்பீர்களா?","hi":"क्या आप छोटे समारोहों के लिए भी पॉपकॉर्न व कॉटन कैंडी स्टॉल लगाते हैं?"},"a6":{"ta":"ஆம் — திருமணம் மட்டுமல்ல, பிறந்தநாள், புதுமனை புகுவிழா, பள்ளி நிகழ்ச்சிகளுக்கும்.","hi":"हां — जन्मदिन, गृहप्रवेश और स्कूल कार्यक्रमों के लिए भी, सिर्फ शादियों के लिए नहीं।"},"q7":{"ta":"விலை விவரம் எப்படி பெறுவது?","hi":"कोटेशन कैसे मिलेगा?"},"a7":{"ta":"எங்களை அழைக்கவும் அல்லது வாட்ஸ்அப் செய்யவும், அல்லது தொடர்பு பக்கத்தில் உள்ள படிவத்தை பயன்படுத்தவும். விரைவில் பதிலளிப்போம்.","hi":"हमें कॉल या व्हाट्सऐप करें, या संपर्क पेज का फॉर्म भरें। हम जल्दी जवाब देंगे।"},"cta.h2":{"ta":"உங்கள் சிறப்பு நாளை திட்டமிட தயாரா?","hi":"अपने खास दिन की योजना बनाने को तैयार?"},"cta.p":{"ta":"உங்கள் தேதியை சொல்லுங்கள், மீதியை நாங்கள் பார்த்துக்கொள்கிறோம்.","hi":"अपनी तारीख बताइए, बाकी हम संभाल लेंगे।"},"ct.form":{"ta":"உங்கள் கொண்டாட்டத்தை திட்டமிடுங்கள்","hi":"अपने उत्सव की योजना बनाएं"},"ct.name":{"ta":"உங்கள் பெயர்","hi":"आपका नाम"},"ct.phone":{"ta":"தொலைபேசி எண்","hi":"फ़ोन नंबर"},"ct.type":{"ta":"நிகழ்ச்சி வகை","hi":"इवेंट का प्रकार"},"ct.date":{"ta":"நிகழ்ச்சி தேதி","hi":"इवेंट की तारीख"},"ct.guests":{"ta":"விருந்தினர்கள் (தோராயமாக)","hi":"मेहमान (लगभग)"},"ct.venue":{"ta":"அரங்கம் / பகுதி","hi":"वेन्यू / क्षेत्र"},"ct.msg":{"ta":"உங்கள் தேவைகள்","hi":"आपकी ज़रूरतें"},"ct.msg.ph":{"ta":"தீம், நிறங்கள், உணவு யோசனைகள், மற்றவை…","hi":"थीम, रंग, मेन्यू के विचार, कुछ और…"},"ct.name.ph":{"ta":"எ.கா. முருகன்","hi":"जैसे: मुरुगन"},"ct.venue.ph":{"ta":"மண்டபம் பெயர் அல்லது ஊர்","hi":"हॉल का नाम या शहर"},"ct.select":{"ta":"நிகழ்ச்சியை தேர்வு செய்க…","hi":"इवेंट चुनें…"},"ct.other":{"ta":"மற்றவை","hi":"अन्य"},"ct.send":{"ta":"வாட்ஸ்அப்பில் அனுப்பு","hi":"व्हाट्सऐप पर भेजें"},"ct.err":{"ta":"இதை சரியாக நிரப்பவும்","hi":"कृपया इसे सही भरें"},"ct.call":{"ta":"எங்களை அழைக்க","hi":"कॉल करें"},"ct.email":{"ta":"மின்னஞ்சல்","hi":"ईमेल"},"ct.visit":{"ta":"முகவரி","hi":"पता"},"ct.hours":{"ta":"வேலை நேரம்","hi":"कार्य समय"},"form.toast":{"ta":"வாட்ஸ்அப் திறக்கிறது — Send அழுத்துங்கள்!","hi":"व्हाट्सऐप खुल रहा है — बस Send दबाएं!"},"ft.about":{"ta":"திருமண அலங்காரம், ராஜ விருந்து மற்றும் கொண்டாட்ட ஸ்டால்கள் — திருநெல்வேலியில் இந்திய பாரம்பரியத்துடன் உருவாக்கப்படுகிறது.","hi":"शादी की सजावट, शाही कैटरिंग और उत्सव स्टॉल — तिरुनेलवेली में भारतीय परंपरा के साथ।"},"ft.links":{"ta":"விரைவு இணைப்புகள்","hi":"त्वरित लिंक"},"ft.copy":{"ta":"© 2026 கிங் ஈவென்ட்ஸ், களந்தபனை, திருநெல்வேலி. அனைத்து உரிமைகளும் பாதுகாக்கப்பட்டவை.","hi":"© 2026 किंग इवेंट्स, कलंथपनई, तिरुनेलवेली। सर्वाधिकार सुरक्षित।"},"btn.home":{"ta":"முகப்புக்கு திரும்ப","hi":"होम पर वापस जाएं"},"title.404":{"ta":"பக்கம் கிடைக்கவில்லை | கிங் ஈவென்ட்ஸ், திருநெல்வேலி","hi":"पेज नहीं मिला | किंग इवेंट्स, तिरुनेलवेली"},"title.home":{"ta":"கிங் ஈவென்ட்ஸ் | திருநெல்வேலி திருமண அலங்காரம் & கேட்டரிங்","hi":"किंग इवेंट्स | तिरुनेलवेली में शादी सजावट व कैटरिंग"},"title.services":{"ta":"சேவைகள் | கிங் ஈவென்ட்ஸ், திருநெல்வேலி","hi":"सेवाएं | किंग इवेंट्स, तिरुनेलवेली"},"title.packages":{"ta":"பேக்கேஜ்கள் | கிங் ஈவென்ட்ஸ், திருநெல்வேலி","hi":"पैकेज | किंग इवेंट्स, तिरुनेलवेली"},"title.gallery":{"ta":"கேலரி | கிங் ஈவென்ட்ஸ், திருநெல்வேலி","hi":"गैलरी | किंग इवेंट्स, तिरुनेलवेली"},"title.about":{"ta":"எங்களை பற்றி | கிங் ஈவென்ட்ஸ், திருநெல்வேலி","hi":"हमारे बारे में | किंग इवेंट्स, तिरुनेलवेली"},"title.faq":{"ta":"கேள்விகள் | கிங் ஈவென்ட்ஸ், திருநெல்வேலி","hi":"सवाल | किंग इवेंट्स, तिरुनेलवेली"},"title.contact":{"ta":"தொடர்பு | கிங் ஈவென்ட்ஸ், திருநெல்வேலி","hi":"संपर्क | किंग इवेंट्स, तिरुनेलवेली"}};
